function Brand({ light = false }: { light?: boolean }) {
  return (
    <Link href="/" className="flex items-center gap-3" data-testid="link-brand">
      <span className={`grid h-9 w-9 place-items-center rounded-xl ${light ? 'bg-[hsl(var(--accent))] text-[hsl(var(--foreground))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`}>
        <Leaf size={18} strokeWidth={2.5} />
      </span>
      <span className="leading-none"><strong className="block text-sm tracking-tight">CivicCycle</strong><small className={`mt-1 block text-[9px] uppercase tracking-[.18em] ${light ? 'text-white/55' : 'text-muted-foreground'}`}>waste operations</small></span>
    </Link>
  );
}

function Button({ children, variant = 'primary', className = '', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'quiet' | 'outline' | 'danger' }) {
  const styles = {
    primary: 'bg-primary text-primary-foreground hover:brightness-110',
    quiet: 'bg-secondary text-secondary-foreground hover:bg-muted',
    outline: 'border border-border bg-card text-foreground hover:bg-muted',
    danger: 'bg-destructive text-destructive-foreground hover:brightness-110',
  };
  return <button className={`inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2.5 text-xs font-bold transition disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} {...props}>{children}</button>;
}

function Status({ value }: { value: string }) {
  const normalized = value.toLowerCase();
  const tone = ['resolved', 'completed', 'accepted', 'active', 'in_progress'].includes(normalized) ? 'green' : ['critical', 'missed', 'rejected', 'suspended'].includes(normalized) ? 'red' : ['submitted', 'acknowledged', 'assigned', 'pending', 'medium', 'high'].includes(normalized) ? 'amber' : 'slate';
  return <span className={`status status-${tone}`} data-testid={`status-${normalized}`}>{value.replaceAll('_', ' ')}</span>;
}

function LoadingState({ label = 'Loading live operations' }: { label?: string }) {
  return <div className="grid gap-3" data-testid="state-loading">{[1, 2, 3].map((n) => <div key={n} className="h-16 animate-pulse rounded-xl bg-muted/70" />)}<p className="text-xs text-muted-foreground">{label}…</p></div>;
}

function ErrorState({ retry, label = 'We could not load this view.' }: { retry?: () => void; label?: string }) {
  return <div className="surface grid place-items-center gap-3 rounded-2xl p-12 text-center" data-testid="state-error"><span className="grid h-12 w-12 place-items-center rounded-full bg-destructive/10 text-destructive"><AlertCircle /></span><div><p className="font-bold">{label}</p><p className="mt-1 text-xs text-muted-foreground">Check the connection and try again.</p></div>{retry && <Button variant="outline" onClick={retry} data-testid="button-retry"><RefreshCw size={14} /> Retry</Button>}</div>;
}

function EmptyState({ icon: Icon = PackageCheck, title, text, action }: { icon?: IconType; title: string; text: string; action?: ReactNode }) {
  return <div className="surface grid place-items-center gap-3 rounded-2xl p-12 text-center" data-testid="state-empty"><span className="grid h-12 w-12 place-items-center rounded-full bg-secondary text-primary"><Icon size={20} /></span><div><p className="font-bold">{title}</p><p className="mt-1 max-w-sm text-xs leading-5 text-muted-foreground">{text}</p></div>{action}</div>;
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description?: string; actions?: ReactNode }) {
  return <header className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end rise"><div><p className="eyebrow mb-2">{eyebrow ?? 'CivicCycle operations'}</p><h1 className="text-2xl font-extrabold tracking-[-.055em] sm:text-3xl">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{actions && <div className="flex items-center gap-2">{actions}</div>}</header>;
}

function StatCard({ label, value, detail, icon: Icon = Activity, tone = 'primary' }: { label: string; value: string | number; detail?: string; icon?: IconType; tone?: 'primary' | 'accent' | 'danger' }) {
  const color = tone === 'danger' ? 'text-destructive bg-destructive/10' : tone === 'accent' ? 'text-accent-foreground bg-accent/20' : 'text-primary bg-primary/10';
  return <div className="surface rounded-2xl p-4" data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><span className={`grid h-9 w-9 place-items-center rounded-xl ${color}`}><Icon size={17} /></span><span className="mono text-[10px] text-muted-foreground">LIVE</span></div><div className="mt-5"><p className="metric-number">{value}</p><p className="mt-1 text-xs font-semibold text-muted-foreground">{label}</p>{detail && <p className="mt-2 text-[11px] text-muted-foreground">{detail}</p>}</div></div>;
}

function Shell({ children, role }: { children: ReactNode; role: 'citizen' | 'collector' | 'admin' }) {
  const [location, setLocation] = useLocation();
  const [open, setOpen] = useState(false);
  const logout = useLogout();
  const current = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), enabled: true, retry: false } });
  const user = current.data;
  const links = roleLinks[role];
  const doLogout = () => logout.mutate(undefined, { onSuccess: () => setLocation('/login') });
  return <div className="app-shell noise flex"><aside className={`sidebar flex w-[248px] shrink-0 flex-col ${open ? 'open' : ''}`}><div className="flex items-center justify-between px-5 py-6"><Brand light /><button className="text-white/60 md:hidden" onClick={() => setOpen(false)} data-testid="button-close-menu"><X size={20} /></button></div><div className="mx-4 mb-6 rounded-xl border border-white/10 bg-white/5 p-3"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-[hsl(var(--accent))] text-xs font-extrabold text-[hsl(var(--foreground))]">{user?.initials ?? (role === 'admin' ? 'OP' : role === 'collector' ? 'JT' : 'MA')}</span><div className="min-w-0"><p className="truncate text-xs font-bold">{user?.fullName ?? (role === 'admin' ? 'Operations desk' : role === 'collector' ? 'Jordan Tran' : 'Maya Alvarez')}</p><p className="mt-0.5 text-[10px] capitalize text-white/45">{role} account</p></div></div></div><nav className="flex-1 space-y-1 px-3">{links.map(([label, href, icon]) => { const Icon = iconMap[icon]; const active = location === href || (href !== roleHome[role] && location.startsWith(href)); return <Link key={href} href={href} onClick={() => setOpen(false)} className={`sidebar-link flex items-center gap-3 rounded-lg px-3 py-2.5 text-xs font-semibold ${active ? 'active' : ''}`} data-testid={`link-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={16} /><span>{label}</span>{label === 'Notifications' && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-accent" />}</Link>; })}</nav><div className="border-t border-white/10 p-3"><button onClick={doLogout} disabled={logout.isPending} className="sidebar-link flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-xs font-semibold" data-testid="button-logout"><LogOut size={16} /> Sign out</button></div></aside><main className="min-w-0 flex-1"><div className="flex h-16 items-center justify-between border-b border-border bg-background/85 px-4 backdrop-blur sm:px-8"><button className="rounded-lg p-2 hover:bg-muted md:hidden" onClick={() => setOpen(true)} data-testid="button-open-menu"><Menu size={20} /></button><div className="hidden items-center gap-2 text-[11px] text-muted-foreground md:flex"><span className="h-2 w-2 rounded-full bg-primary dot-pulse" /> Service network stable <span className="mx-2 text-border">/</span> {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}</div><div className="ml-auto flex items-center gap-3"><Link href={`/${role}/notifications`} className="relative rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-foreground" data-testid="link-header-notifications"><Bell size={18} /><span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-accent" /></Link><div className="hidden h-5 w-px bg-border sm:block" /><span className="hidden text-xs font-semibold sm:block">{user?.fullName ?? 'Field account'}</span><span className="grid h-8 w-8 place-items-center rounded-full bg-secondary text-[10px] font-extrabold text-primary">{user?.initials ?? 'CC'}</span></div></div><div className="mx-auto max-w-[1500px] px-4 py-7 sm:px-8 lg:px-10">{children}</div></main></div>;
}

function PublicFrame({ children }: { children: ReactNode }) {
  return <div className="min-h-[100dvh] bg-background">{children}</div>;
}

const landingSteps: [string, string, string, IconType][] = [['01', 'See the schedule', 'Residents know the next pickup, the waste type, and what to do if plans change.', CalendarDays], ['02', 'Send a precise signal', 'A location-aware report reaches the right queue with urgency attached.', MessageSquare], ['03', 'Close the loop', 'Crews update work in the field. Everyone can see progress without chasing.', Check]];

function Landing() {
  return <PublicFrame><nav className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 sm:px-8"><Brand /><div className="hidden items-center gap-7 text-xs font-semibold text-muted-foreground md:flex"><a href="#how" data-testid="link-how-it-works">How it works</a><a href="#trust" data-testid="link-service-trust">Service trust</a><Link href="/login" className="text-foreground" data-testid="link-sign-in-nav">Sign in <ArrowRight className="ml-1 inline" size={13} /></Link></div><Link href="/login" className="rounded-lg bg-primary px-3.5 py-2.5 text-xs font-bold text-primary-foreground md:hidden" data-testid="link-mobile-sign-in">Sign in</Link></nav><section className="relative overflow-hidden"><div className="absolute right-[-10%] top-[-15%] -z-0 h-[560px] w-[560px] rounded-full bg-secondary/70 blur-3xl" /><div className="mx-auto grid max-w-7xl items-center gap-14 px-5 pb-20 pt-14 sm:px-8 lg:grid-cols-[1.05fr_.95fr] lg:pb-28 lg:pt-24"><div className="relative z-10 rise"><p className="eyebrow mb-5 flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-accent" /> Municipal service, made visible</p><h1 className="max-w-2xl text-5xl font-extrabold leading-[.98] tracking-[-.08em] sm:text-7xl">A cleaner city starts with <span className="text-primary">a clear signal.</span></h1><p className="mt-7 max-w-lg text-base leading-7 text-muted-foreground">CivicCycle connects residents, collection crews, and the people who keep the network moving. Report what you see. Know what happens next.</p><div className="mt-8 flex flex-wrap items-center gap-3"><Link href="/register" className="inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-3.5 text-xs font-bold text-primary-foreground hover:brightness-110" data-testid="link-get-started">Create a resident account <ArrowRight size={15} /></Link><Link href="/login" className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-5 py-3.5 text-xs font-bold hover:bg-muted" data-testid="link-demo-access">Explore the workspace <PanelLeft size={15} /></Link></div><div className="mt-10 flex items-center gap-5 text-[11px] text-muted-foreground"><span className="flex items-center gap-2"><Check size={14} className="text-primary" /> Live collection status</span><span className="flex items-center gap-2"><Check size={14} className="text-primary" /> Human escalation</span></div></div><div className="relative rise delay-1"><div className="grid-lines absolute -inset-6 rounded-[2rem] opacity-60" /><div className="surface relative overflow-hidden rounded-[1.75rem] p-4 sm:p-6"><div className="flex items-center justify-between border-b border-border pb-4"><div><p className="eyebrow">North district / today</p><p className="mt-2 text-sm font-bold">Service pulse</p></div><span className="status status-green">On track</span></div><div className="grid grid-cols-2 gap-3 py-5"><div className="rounded-xl bg-secondary/60 p-4"><p className="mono text-[10px] text-muted-foreground">ROUTES ACTIVE</p><p className="mt-2 text-3xl font-extrabold tracking-[-.07em]">18</p><div className="mt-3 progress-track"><div className="progress-fill w-[76%]" /></div></div><div className="rounded-xl bg-primary p-4 text-primary-foreground"><p className="mono text-[10px] opacity-65">COLLECTED</p><p className="mt-2 text-3xl font-extrabold tracking-[-.07em]">76%</p><p className="mt-3 text-[10px] opacity-65">of today’s schedule</p></div></div><div className="rounded-xl border border-border p-4"><div className="mb-4 flex items-center justify-between"><span className="text-xs font-bold">Route activity</span><span className="mono text-[10px] text-muted-foreground">06:00 — 14:00</span></div>{[['07:12', 'Maple & 8th', 'completed'], ['08:40', 'Oakview apartments', 'in progress'], ['09:25', 'Cedar transfer point', 'pending']].map(([time, place, state]) => <div className="flex items-center gap-3 border-t border-border py-3 first:border-0" key={place}><span className="mono w-10 text-[10px] text-muted-foreground">{time}</span><span className="h-2 w-2 rounded-full bg-primary" /><span className="flex-1 text-xs font-semibold">{place}</span><Status value={state} /></div>)}</div><div className="mt-4 flex items-center gap-3 rounded-xl bg-accent/20 p-3"><Sparkles size={15} className="text-accent-foreground" /><p className="text-[11px] leading-4">Signal intelligence flagged one high-priority overflow for crew review.</p></div></div></div></div></section><section id="how" className="border-y border-border bg-card"><div className="mx-auto grid max-w-7xl gap-0 md:grid-cols-3">{landingSteps.map(([n, title, text, Icon]) => <div key={n} className="border-b border-border p-8 last:border-0 md:border-b-0 md:border-r md:last:border-r-0 lg:p-12"><span className="mono text-xs text-accent-foreground">{n}</span><div className="mt-10 grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><Icon size={18} /></div><h2 className="mt-5 text-lg font-extrabold tracking-tight">{title}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{text}</p></div>)}</div></section><section id="trust" className="mx-auto max-w-7xl px-5 py-20 sm:px-8 lg:py-28"><div className="grid gap-12 lg:grid-cols-[.8fr_1.2fr]"><div><p className="eyebrow">Designed for the people behind the route</p><h2 className="mt-4 max-w-md text-4xl font-extrabold leading-tight tracking-[-.07em]">Operational calm, even on a messy day.</h2></div><div className="grid gap-4 sm:grid-cols-2"><div className="surface rounded-2xl p-6"><ShieldCheck className="text-primary" /><h3 className="mt-8 font-bold">A visible chain of care</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Every report has an owner, a status, and a next action — not a black hole.</p></div><div className="surface rounded-2xl p-6"><Gauge className="text-accent-foreground" /><h3 className="mt-8 font-bold">Signals over noise</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Priority, zone, and service quality live together so teams act on what matters first.</p></div></div></div></section><footer className="border-t border-border px-5 py-7 sm:px-8"><div className="mx-auto flex max-w-7xl flex-col justify-between gap-3 text-[11px] text-muted-foreground sm:flex-row"><span>© 2025 CivicCycle municipal services</span><span>Built for cleaner, more accountable streets.</span></div></footer></PublicFrame>;
}

function Login() {
  const [, setLocation] = useLocation();
  const login = useLogin();
  const [email, setEmail] = useState('citizen@example.com');
  const [password, setPassword] = useState('WasteDemo#2026');
  const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); login.mutate({ data: { email, password } }, { onSuccess: (res) => setLocation(roleHome[res.user.role]), onError: () => setError('That sign-in did not work. Try one of the demo workspaces below.') }); };
  const demo = (role: 'citizen' | 'collector' | 'admin', nextEmail: string) => { setEmail(nextEmail); setPassword('WasteDemo#2026'); login.mutate({ data: { email: nextEmail, password: 'WasteDemo#2026' } }, { onSuccess: () => setLocation(roleHome[role]), onError: () => setError('Demo access is unavailable right now. You can still try the form.') }); };
  return <PublicFrame><div className="grid min-h-[100dvh] lg:grid-cols-[.9fr_1.1fr]"><div className="hidden bg-[hsl(var(--sidebar))] p-10 text-white lg:flex lg:flex-col lg:justify-between"><Brand light /><div className="max-w-md"><p className="eyebrow text-[hsl(var(--accent))]">Workspace access</p><h1 className="mt-5 text-5xl font-extrabold leading-[.98] tracking-[-.08em]">Good service is a shared responsibility.</h1><p className="mt-6 text-sm leading-7 text-white/55">Sign in to report a concern, run today’s route, or keep an eye on the network.</p></div><p className="text-[11px] text-white/35">CivicCycle / municipal operations platform</p></div><div className="flex items-center justify-center px-5 py-10"><div className="w-full max-w-md"><div className="mb-8 lg:hidden"><Brand /></div><div className="mb-8"><p className="eyebrow">Welcome back</p><h2 className="mt-3 text-3xl font-extrabold tracking-[-.06em]">Sign in to CivicCycle</h2><p className="mt-2 text-sm text-muted-foreground">Use your municipal account or preview a role.</p></div><form onSubmit={submit} className="grid gap-4"><label className="grid gap-2 text-xs font-bold">Email<input autoComplete="username" className="h-11 rounded-lg border border-input bg-card px-3 text-sm outline-none ring-primary/30 focus:ring-2" type="email" value={email} onChange={(e) => setEmail(e.target.value)} data-testid="input-email" /></label><label className="grid gap-2 text-xs font-bold">Password<input autoComplete="current-password" className="h-11 rounded-lg border border-input bg-card px-3 text-sm outline-none ring-primary/30 focus:ring-2" type="password" value={password} onChange={(e) => setPassword(e.target.value)} data-testid="input-password" /></label>{error && <p className="rounded-lg bg-destructive/10 p-3 text-xs font-semibold text-destructive" data-testid="status-login-error">{error}</p>}<Button type="submit" disabled={login.isPending} className="mt-2 h-11" data-testid="button-submit-login">{login.isPending ? 'Signing in…' : 'Sign in'} <ArrowRight size={15} /></Button></form><div className="my-7 flex items-center gap-3 text-[10px] uppercase tracking-widest text-muted-foreground"><span className="h-px flex-1 bg-border" /> Demo workspaces <span className="h-px flex-1 bg-border" /></div><div className="grid gap-2">{[['Citizen view', 'citizen@example.com', 'citizen'], ['Collector view', 'collector@example.com', 'collector'], ['Admin view', 'admin@example.com', 'admin']].map(([label, nextEmail, role]) => <button key={role} onClick={() => demo(role as 'citizen' | 'collector' | 'admin', nextEmail)} className="flex items-center justify-between rounded-lg border border-border bg-card px-4 py-3 text-left text-xs font-bold hover:bg-muted" data-testid={`button-demo-${role}`}><span className="flex items-center gap-3"><span className="h-2 w-2 rounded-full bg-primary" /> {label}</span><ChevronRight size={15} className="text-muted-foreground" /></button>)}</div><p className="mt-7 text-center text-xs text-muted-foreground">New to CivicCycle? <Link href="/register" className="font-bold text-primary" data-testid="link-register">Create a resident account</Link></p></div></div></div></PublicFrame>;
}

function Register() {
  const [, setLocation] = useLocation();
  const register = useRegister();
  const [form, setForm] = useState({ fullName: '', email: '', phone: '', password: '', address: '', zone: '' });
  const [error, setError] = useState('');
  const update = (key: keyof typeof form) => (e: ChangeEvent<HTMLInputElement>) => setForm((v) => ({ ...v, [key]: e.target.value }));
  return <PublicFrame><div className="mx-auto grid min-h-[100dvh] max-w-6xl items-center gap-12 px-5 py-10 lg:grid-cols-[.75fr_1fr] lg:px-10"><div><Brand /><p className="eyebrow mt-16">Resident access</p><h1 className="mt-4 max-w-md text-5xl font-extrabold leading-[.98] tracking-[-.08em]">Your street, in the loop.</h1><p className="mt-6 max-w-md text-sm leading-7 text-muted-foreground">Create an account to see collections for your address and send reports directly to the local operations team.</p><div className="mt-8 grid gap-3 text-xs text-muted-foreground"><span className="flex items-center gap-2"><Check size={15} className="text-primary" /> See collection changes as they happen</span><span className="flex items-center gap-2"><Check size={15} className="text-primary" /> Keep a clear record of every report</span></div></div><div className="surface rounded-2xl p-6 sm:p-9"><div className="mb-7"><p className="eyebrow">Create account</p><h2 className="mt-2 text-2xl font-extrabold tracking-[-.05em]">Tell us where you live</h2></div><form className="grid gap-4 sm:grid-cols-2" onSubmit={(e) => { e.preventDefault(); setError(''); register.mutate({ data: form }, { onSuccess: () => setLocation('/citizen'), onError: () => setError('We could not create that account. Check each field and try again.') }); }}><label className="grid gap-2 text-xs font-bold sm:col-span-2">Full name<input required className="field" value={form.fullName} onChange={update('fullName')} data-testid="input-register-name" /></label><label className="grid gap-2 text-xs font-bold">Email<input required type="email" className="field" value={form.email} onChange={update('email')} data-testid="input-register-email" /></label><label className="grid gap-2 text-xs font-bold">Phone<input required className="field" value={form.phone} onChange={update('phone')} data-testid="input-register-phone" /></label><label className="grid gap-2 text-xs font-bold sm:col-span-2">Home address<input required className="field" placeholder="Street and number" value={form.address} onChange={update('address')} data-testid="input-register-address" /></label><label className="grid gap-2 text-xs font-bold">Zone code<input className="field" placeholder="Optional" value={form.zone} onChange={update('zone')} data-testid="input-register-zone" /></label><label className="grid gap-2 text-xs font-bold">Password<input required type="password" className="field" value={form.password} onChange={update('password')} data-testid="input-register-password" /></label>{error && <p className="rounded-lg bg-destructive/10 p-3 text-xs font-semibold text-destructive sm:col-span-2" data-testid="status-register-error">{error}</p>}<Button type="submit" disabled={register.isPending} className="mt-2 h-11 sm:col-span-2" data-testid="button-submit-register">{register.isPending ? 'Creating your account…' : 'Create resident account'} <ArrowRight size={15} /></Button></form><p className="mt-6 text-center text-xs text-muted-foreground">Already have access? <Link href="/login" className="font-bold text-primary" data-testid="link-login">Sign in</Link></p></div></div></PublicFrame>;
}

function CitizenOverview() {
  const q = useGetCitizenDashboard({ query: { queryKey: getGetCitizenDashboardQueryKey() } }); const d = q.data;
  return <Shell role="citizen"><PageHeader eyebrow="Resident overview" title="Good morning, Maya." description="Here’s what is happening with service around your address." actions={<Link href="/citizen/complaints/new" className="inline-flex items-center gap-2 rounded-lg bg-primary px-3.5 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-new-complaint"><Plus size={15} /> Report an issue</Link>} />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : d ? <><div className="grid gap-4 lg:grid-cols-[1.35fr_1fr_1fr]"><div className="surface relative overflow-hidden rounded-2xl bg-[hsl(var(--primary))] p-6 text-primary-foreground"><div className="absolute right-[-20px] top-[-20px] h-36 w-36 rounded-full border-[20px] border-white/10" /><p className="eyebrow text-white/60">Next collection</p><div className="mt-5 flex items-end justify-between"><div><p className="text-4xl font-extrabold tracking-[-.08em]">{new Date(d.nextCollection.date).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}</p><p className="mt-2 text-sm text-white/70">{d.nextCollection.time} · {d.nextCollection.wasteType}</p></div><CalendarDays size={34} className="mb-1 opacity-70" /></div><div className="mt-7 flex items-center justify-between border-t border-white/15 pt-4 text-xs"><span>{d.nextCollection.location}</span><Status value={d.nextCollection.status} /></div></div><StatCard label="Open complaints" value={d.openComplaints} detail="Tracked by the local team" icon={MessageSquare} tone="accent" /><StatCard label="Unread notifications" value={d.unreadNotifications} detail="Updates waiting for you" icon={Bell} /></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="surface rounded-2xl p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Recent activity</p><h2 className="mt-2 text-lg font-extrabold tracking-tight">Your service trail</h2></div><Link href="/citizen/complaints" className="text-xs font-bold text-primary" data-testid="link-view-complaints">View complaints <ArrowRight className="ml-1 inline" size={13} /></Link></div><div className="mt-5 divide-y divide-border">{d.recentActivity?.length ? d.recentActivity.map((item, i) => <div className="flex gap-4 py-4 first:pt-0 last:pb-0" key={`${item.title}-${i}`} data-testid={`activity-${i}`}><span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-primary" /><div className="min-w-0 flex-1"><div className="flex flex-wrap justify-between gap-2"><p className="text-xs font-bold">{item.title}</p><span className="mono text-[10px] text-muted-foreground">{item.timestamp}</span></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{item.description}</p></div></div>) : <EmptyState icon={Activity} title="No recent activity" text="Your updates will appear here as the service team works." />}</div></section><section className="rounded-2xl bg-secondary p-6"><div className="flex items-center gap-2 text-primary"><Sparkles size={17} /><p className="eyebrow">Today’s useful tip</p></div><p className="mt-8 text-xl font-extrabold leading-snug tracking-[-.04em]">{d.tip}</p><Link href="/citizen/assistant" className="mt-8 inline-flex items-center gap-2 text-xs font-bold text-primary" data-testid="link-ask-guide">Ask the waste guide <ArrowRight size={14} /></Link></section></div></> : <EmptyState title="Nothing to show yet" text="Your collection details will appear once your address is connected." />}</Shell>;
}

function Schedules() {
  const q = useGetCitizenSchedules({ query: { queryKey: getGetCitizenSchedulesQueryKey() } }); const [tab, setTab] = useState('upcoming'); const rows = q.data ?? []; const filtered = rows.filter((r) => tab === 'upcoming' ? !['completed', 'missed'].includes(r.status) : ['completed', 'missed'].includes(r.status));
  return <Shell role="citizen"><PageHeader eyebrow="Resident schedule" title="Collections" description="Know what is coming to your address, and what has already been completed." /><div className="mb-5 flex gap-1 rounded-xl bg-muted p-1 w-fit"><button onClick={() => setTab('upcoming')} className={`rounded-lg px-4 py-2 text-xs font-bold ${tab === 'upcoming' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} data-testid="button-tab-upcoming">Upcoming</button><button onClick={() => setTab('past')} className={`rounded-lg px-4 py-2 text-xs font-bold ${tab === 'past' ? 'bg-card shadow-sm' : 'text-muted-foreground'}`} data-testid="button-tab-past">Past collections</button></div>{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : filtered.length ? <div className="surface overflow-hidden rounded-2xl"><div className="hidden grid-cols-[1.1fr_1fr_1fr_1fr_auto] gap-4 border-b border-border bg-muted/45 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground sm:grid"><span>Date</span><span>Material</span><span>Location</span><span>Zone</span><span>Status</span></div>{filtered.map((r) => <div className="grid gap-3 border-b border-border px-5 py-4 last:border-0 sm:grid-cols-[1.1fr_1fr_1fr_1fr_auto] sm:items-center sm:gap-4" key={r.id} data-testid={`row-schedule-${r.id}`}><div><p className="text-sm font-bold">{new Date(r.date).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}</p><p className="mt-1 text-[11px] text-muted-foreground">{r.time}</p></div><p className="text-xs font-semibold">{r.wasteType}</p><p className="text-xs text-muted-foreground">{r.location}</p><p className="mono text-[10px] text-muted-foreground">{r.zone}</p><Status value={r.status} /></div>)}</div> : <EmptyState title={tab === 'upcoming' ? 'No upcoming collections' : 'No past collections'} text="When a collection is scheduled for your address, it will appear here." />}</Shell>;
}

function CitizenComplaints() {
  const q = useGetCitizenComplaints({ query: { queryKey: getGetCitizenComplaintsQueryKey() } }); const rows = q.data ?? [];
  return <Shell role="citizen"><PageHeader eyebrow="Resident reports" title="My complaints" description="A clear record of what you reported and where it stands." actions={<Link href="/citizen/complaints/new" className="inline-flex items-center gap-2 rounded-lg bg-primary px-3.5 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-new-complaint-list"><Plus size={15} /> New complaint</Link>} />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : rows.length ? <div className="grid gap-3">{rows.map((c) => <Link href={`/citizen/complaints/${c.id}`} key={c.id} className="surface group flex flex-col gap-4 rounded-2xl p-5 hover:-translate-y-0.5 sm:flex-row sm:items-center sm:justify-between" data-testid={`card-complaint-${c.id}`}><div className="flex min-w-0 gap-4"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><FileText size={17} /></span><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-sm font-bold">{c.title}</p><Status value={c.severity} /></div><p className="mt-1 line-clamp-1 text-xs text-muted-foreground">{c.location} · {c.category}</p><p className="mono mt-2 text-[10px] text-muted-foreground">Reported {new Date(c.createdAt).toLocaleDateString()}</p></div></div><div className="flex items-center gap-3 sm:pl-8"><Status value={c.status} /><ChevronRight size={16} className="text-muted-foreground transition-transform group-hover:translate-x-1" /></div></Link>)}</div> : <EmptyState icon={FileText} title="No complaints yet" text="If something needs attention, send the team a precise signal and we’ll keep you posted." action={<Link href="/citizen/complaints/new" className="mt-2 inline-flex items-center gap-2 rounded-lg bg-primary px-3.5 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-empty-new-complaint"><Plus size={15} /> Report an issue</Link>} />}</Shell>;
}

function NewComplaint() {
  const [, setLocation] = useLocation(); const qc = useQueryClient(); const create = useCreateCitizenComplaint(); const [form, setForm] = useState({ category: 'Overflowing bin', title: '', description: '', location: '', severity: 'medium' }); const [error, setError] = useState('');
  const update = (key: keyof typeof form) => (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => setForm((v) => ({ ...v, [key]: e.target.value }));
  return <Shell role="citizen"><PageHeader eyebrow="New report" title="Send a clear signal" description="The more specific the report, the faster the right crew can act." /><div className="mx-auto max-w-3xl"><form className="surface grid gap-5 rounded-2xl p-5 sm:p-8" onSubmit={(e) => { e.preventDefault(); setError(''); create.mutate({ data: { ...form, severity: form.severity as 'low' | 'medium' | 'high' | 'critical' } }, { onSuccess: (c) => { qc.invalidateQueries({ queryKey: getGetCitizenComplaintsQueryKey() }); setLocation(`/citizen/complaints/${c.id}`); }, onError: () => setError('We could not send this report. Please check the details and try again.') }); }}><div className="grid gap-5 sm:grid-cols-2"><label className="grid gap-2 text-xs font-bold">Category<select className="field" value={form.category} onChange={update('category')} data-testid="select-complaint-category"><option>Overflowing bin</option><option>Missed collection</option><option>Illegal dumping</option><option>Damaged bin</option><option>Other service issue</option></select></label><label className="grid gap-2 text-xs font-bold">Urgency<select className="field" value={form.severity} onChange={update('severity')} data-testid="select-complaint-severity"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="critical">Critical</option></select></label></div><label className="grid gap-2 text-xs font-bold">Short title<input required minLength={5} className="field" placeholder="What needs attention?" value={form.title} onChange={update('title')} data-testid="input-complaint-title" /></label><label className="grid gap-2 text-xs font-bold">Location<input required minLength={3} className="field" placeholder="Street, landmark, or collection point" value={form.location} onChange={update('location')} data-testid="input-complaint-location" /></label><label className="grid gap-2 text-xs font-bold">What happened?<textarea required minLength={10} rows={5} className="field resize-none py-3" placeholder="Add useful detail: when you noticed it, what is affected, and anything a crew should know." value={form.description} onChange={update('description')} data-testid="textarea-complaint-description" /></label>{error && <p className="rounded-lg bg-destructive/10 p-3 text-xs font-semibold text-destructive" data-testid="status-complaint-error">{error}</p>}<div className="flex flex-col-reverse justify-end gap-2 border-t border-border pt-5 sm:flex-row"><Link href="/citizen/complaints" className="inline-flex items-center justify-center rounded-lg px-4 py-2.5 text-xs font-bold text-muted-foreground hover:bg-muted" data-testid="link-cancel-complaint">Cancel</Link><Button type="submit" disabled={create.isPending} data-testid="button-submit-complaint">{create.isPending ? 'Sending report…' : 'Send report'} <ArrowRight size={15} /></Button></div></form></div></Shell>;
}

function ComplaintDetail() {
  const { id = '' } = useParams<{ id: string }>(); const q = useGetCitizenComplaint(id, { query: { queryKey: getGetCitizenComplaintQueryKey(id), enabled: !!id } }); const c = q.data;
  return <Shell role="citizen"><Link href="/citizen/complaints" className="mb-6 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-foreground" data-testid="link-back-complaints">← All complaints</Link>{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : c ? <><PageHeader eyebrow={`${c.category} / ${c.id.slice(0, 8)}`} title={c.title} description={c.description} /><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="surface rounded-2xl p-6"><div className="flex items-center justify-between border-b border-border pb-5"><div><p className="eyebrow">Progress timeline</p><p className="mt-2 text-sm font-bold">Your report is moving through the team</p></div><Status value={c.status} /></div><div className="mt-7">{c.timeline?.map((item, i) => <div className="relative flex gap-4 pb-7 last:pb-0" key={`${item.timestamp}-${i}`}><div className="relative flex w-4 justify-center"><span className={`z-10 mt-1.5 h-3 w-3 rounded-full border-2 border-card ${i === c.timeline.length - 1 ? 'bg-primary' : 'bg-muted-foreground'}`} />{i < c.timeline.length - 1 && <span className="absolute top-4 h-full w-px bg-border" />}</div><div className="flex-1"><div className="flex flex-wrap justify-between gap-2"><p className="text-xs font-bold capitalize">{item.status.replaceAll('_', ' ')}</p><span className="mono text-[10px] text-muted-foreground">{item.timestamp}</span></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{item.note ?? 'Status updated by the service team.'}</p></div></div>)}</div></section><aside className="grid content-start gap-4"><div className="surface rounded-2xl p-5"><p className="eyebrow">Report details</p><dl className="mt-5 grid gap-4 text-xs"><div><dt className="text-muted-foreground">Location</dt><dd className="mt-1 font-bold">{c.location}</dd></div><div><dt className="text-muted-foreground">Urgency</dt><dd className="mt-2"><Status value={c.severity} /></dd></div><div><dt className="text-muted-foreground">Assigned collector</dt><dd className="mt-1 font-bold">{c.assignedCollector ?? 'Waiting for assignment'}</dd></div><div><dt className="text-muted-foreground">Last updated</dt><dd className="mono mt-1 text-[10px]">{c.updatedAt ? new Date(c.updatedAt).toLocaleString() : '—'}</dd></div></dl></div><div className="rounded-2xl bg-secondary p-5"><HelpCircle className="text-primary" size={18} /><p className="mt-4 text-sm font-bold">Need to add context?</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Create a new report with any detail the crew should know. We’ll link it to your address.</p><Link href="/citizen/complaints/new" className="mt-4 inline-flex text-xs font-bold text-primary" data-testid="link-add-report-context">New report <ArrowRight className="ml-1" size={14} /></Link></div></aside></div></> : <EmptyState title="Report not found" text="This report may have been removed or the link is out of date." />}</Shell>;
}

function Notifications({ role }: { role: 'citizen' | 'collector' | 'admin' }) {
  const citizenQ = useGetCitizenNotifications({ query: { queryKey: getGetCitizenNotificationsQueryKey(), enabled: role === 'citizen' } });
  const collectorQ = useGetCollectorNotifications({ query: { queryKey: getGetCollectorNotificationsQueryKey(), enabled: role === 'collector' } });
  const mark = useMarkCitizenNotificationRead(); const q = role === 'citizen' ? citizenQ : collectorQ; const rows = q.data ?? [];
  return <Shell role={role}><PageHeader eyebrow={`${role} inbox`} title="Notifications" description="Important changes, surfaced without the noise." />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : rows.length ? <div className="grid gap-3">{rows.map((n) => <div className={`surface flex gap-4 rounded-2xl p-5 ${n.read ? 'opacity-70' : ''}`} key={n.id} data-testid={`notification-${n.id}`}><span className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${n.read ? 'bg-muted text-muted-foreground' : 'bg-accent/20 text-accent-foreground'}`}><Bell size={17} /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap justify-between gap-2"><p className="text-sm font-bold">{n.title}</p><span className="mono text-[10px] text-muted-foreground">{new Date(n.createdAt).toLocaleString()}</span></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{n.message}</p>{!n.read && role === 'citizen' && <button className="mt-3 text-[11px] font-bold text-primary" onClick={() => mark.mutate({ id: n.id }, { onSuccess: () => citizenQ.refetch() })} data-testid={`button-read-${n.id}`}>Mark as read</button>}</div></div>)}</div> : <EmptyState icon={Bell} title="You’re all caught up" text="New service updates will appear here." />}</Shell>;
}

function Profile({ role }: { role: 'citizen' | 'collector' | 'admin' }) {
  const q = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } }); const u = q.data; return <Shell role={role}><PageHeader eyebrow="Account" title="Profile" description="Your identity and service context." /><div className="grid max-w-3xl gap-5 lg:grid-cols-[.7fr_1.3fr]"><div className="surface rounded-2xl p-6"><span className="grid h-16 w-16 place-items-center rounded-2xl bg-primary text-xl font-extrabold text-primary-foreground">{u?.initials ?? 'CC'}</span><h2 className="mt-5 text-xl font-extrabold">{u?.fullName ?? 'Account holder'}</h2><p className="mt-1 text-xs text-muted-foreground">{u?.email ?? '—'}</p><div className="mt-5"><Status value={u?.status ?? 'active'} /></div></div><div className="surface rounded-2xl p-6"><p className="eyebrow">Account details</p><dl className="mt-6 grid gap-5 text-sm"><div><dt className="text-xs text-muted-foreground">Full name</dt><dd className="mt-1 font-bold">{u?.fullName ?? 'Loading'}</dd></div><div><dt className="text-xs text-muted-foreground">Phone</dt><dd className="mt-1 font-bold">{u?.phone ?? 'Not provided'}</dd></div><div><dt className="text-xs text-muted-foreground">Address</dt><dd className="mt-1 font-bold">{u?.address ?? 'Not provided'}</dd></div><div><dt className="text-xs text-muted-foreground">Service zone</dt><dd className="mt-1 font-bold">{u?.zone ?? 'Not assigned'}</dd></div></dl></div></div></Shell>;
}

function Assistant() {
  const ask = useAskWasteAssistant(); const historyQ = useGetAiHistory({ query: { queryKey: getGetAiHistoryQueryKey() } }); const [question, setQuestion] = useState(''); const [answer, setAnswer] = useState<WasteAdvisory | null>(null);
  return <Shell role="citizen"><PageHeader eyebrow="Waste guidance" title="Ask the waste guide" description="A practical answer for sorting, timing, and local service rules." /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="surface overflow-hidden rounded-2xl"><div className="bg-[hsl(var(--sidebar))] p-6 text-white sm:p-8"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[hsl(var(--accent))] text-[hsl(var(--foreground))]"><Sparkles size={19} /></span><div><p className="eyebrow text-[hsl(var(--accent))]">CivicCycle guide</p><p className="mt-1 text-sm font-bold">Small question, useful next step.</p></div></div><div className="mt-10"><textarea rows={4} className="w-full resize-none rounded-xl border border-white/15 bg-white/10 p-4 text-sm text-white outline-none placeholder:text-white/35 focus:border-[hsl(var(--accent))]" placeholder="Can I put a broken toaster in my recycling bin?" value={question} onChange={(e) => setQuestion(e.target.value)} data-testid="textarea-assistant-question" /><Button className="mt-3" disabled={!question.trim() || ask.isPending} onClick={() => ask.mutate({ data: { question, context: null } }, { onSuccess: (res) => { setAnswer(res); setQuestion(''); historyQ.refetch(); } })} data-testid="button-ask-assistant">{ask.isPending ? 'Thinking…' : 'Get guidance'} <ArrowRight size={15} /></Button></div></div>{answer && <div className="border-t border-border p-6" data-testid="card-assistant-answer"><div className="flex items-center justify-between"><span className="status status-green">{answer.category}</span><span className="mono text-[10px] text-muted-foreground">{Math.round(answer.confidence * 100)}% confidence</span></div><p className="mt-5 text-sm leading-7">{answer.answer}</p><div className="mt-5 rounded-xl bg-secondary p-4"><p className="eyebrow">Recommended action</p><p className="mt-2 text-xs font-bold leading-5">{answer.recommendedAction}</p></div>{(answer.safetyNote || answer.localRuleNote) && <div className="mt-4 grid gap-2 text-xs text-muted-foreground">{answer.safetyNote && <p><strong>Safety:</strong> {answer.safetyNote}</p>}{answer.localRuleNote && <p><strong>Local rule:</strong> {answer.localRuleNote}</p>}</div>}</div>}</section><section className="surface rounded-2xl p-6"><p className="eyebrow">Recent questions</p><h2 className="mt-2 text-lg font-extrabold">Your guide history</h2>{historyQ.isLoading ? <div className="mt-5"><LoadingState label="Loading guidance history" /></div> : historyQ.data?.length ? <div className="mt-5 divide-y divide-border">{historyQ.data.slice(0, 6).map((item) => <div className="py-4 first:pt-0" key={item.id}><p className="text-xs font-bold">{item.question}</p><p className="mt-2 line-clamp-2 text-xs leading-5 text-muted-foreground">{item.answer}</p></div>)}</div> : <div className="mt-6"><EmptyState icon={Sparkles} title="No questions yet" text="Ask about sorting or service rules to start your history." /></div>}</section></div></Shell>;
}

function CollectorOverview() {
  const q = useGetCollectorDashboard({ query: { queryKey: getGetCollectorDashboardQueryKey() } }); const d = q.data;
  return <Shell role="collector"><PageHeader eyebrow="Field operations" title="Route desk" description="A focused view of today’s work, exceptions, and handoffs." actions={<Link href="/collector/collections" className="inline-flex items-center gap-2 rounded-lg bg-primary px-3.5 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-collections-today"><ClipboardCheck size={15} /> Open collections</Link>} />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : d ? <><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><StatCard label="Today’s stops" value={d.today} icon={MapPin} /><StatCard label="Pending" value={d.pending} icon={Clock3} tone="accent" /><StatCard label="Completed" value={d.completed} icon={Check} /><StatCard label="Missed" value={d.missed} icon={X} tone="danger" /><StatCard label="Incidents" value={d.incidents} icon={AlertCircle} tone="accent" /></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="surface rounded-2xl p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Assigned work</p><h2 className="mt-2 text-lg font-extrabold">Today’s route</h2></div><Link href="/collector/routes" className="text-xs font-bold text-primary" data-testid="link-all-routes">Full route <ArrowRight className="ml-1 inline" size={13} /></Link></div><div className="mt-5 divide-y divide-border">{d.assignments?.slice(0, 6).map((a) => <div className="flex flex-wrap items-center gap-3 py-4 first:pt-0 last:pb-0" key={a.id} data-testid={`assignment-${a.id}`}><span className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-primary"><MapPin size={15} /></span><div className="min-w-[140px] flex-1"><p className="text-xs font-bold">{a.location}</p><p className="mt-1 text-[11px] text-muted-foreground">{a.wasteType} · {a.time}</p></div><Status value={a.status} /></div>)}</div></section><section className="rounded-2xl bg-secondary p-6"><p className="eyebrow">Field note</p><p className="mt-6 text-lg font-extrabold leading-snug tracking-tight">Keep exceptions visible. A missed stop with a reason is easier to recover than a silent gap.</p><Link href="/collector/incidents" className="mt-7 inline-flex items-center gap-2 text-xs font-bold text-primary" data-testid="link-log-incident">View incidents <ArrowRight size={14} /></Link></section></div></> : <EmptyState title="No route assigned" text="Your dispatcher has not assigned work for today." />}</Shell>;
}

function CollectorAssignments({ focus = 'all' }: { focus?: 'all' | 'collections' }) {
  const q = useGetCollectorAssignments({ query: { queryKey: getGetCollectorAssignmentsQueryKey() } }); const update = useUpdateCollectorAssignmentStatus(); const rows = q.data ?? [];
  return <Shell role="collector"><PageHeader eyebrow="Field worklist" title={focus === 'collections' ? 'Collection tasks' : 'Assigned routes'} description="Update the status at the point of service so the network stays current." />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : rows.length ? <div className="surface overflow-hidden rounded-2xl"><div className="hidden grid-cols-[1.4fr_.9fr_.75fr_.65fr_auto] gap-4 border-b border-border bg-muted/45 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground sm:grid"><span>Stop</span><span>Waste type</span><span>Time</span><span>Status</span><span>Action</span></div>{rows.map((a) => <div className="grid gap-3 border-b border-border px-5 py-4 last:border-0 sm:grid-cols-[1.4fr_.9fr_.75fr_.65fr_auto] sm:items-center sm:gap-4" key={a.id} data-testid={`row-assignment-${a.id}`}><div><p className="text-sm font-bold">{a.location}</p><p className="mt-1 text-[11px] text-muted-foreground">{a.zone} · {a.date}</p></div><p className="text-xs font-semibold">{a.wasteType}</p><p className="mono text-[10px] text-muted-foreground">{a.time}</p><Status value={a.status} /><select className="h-9 rounded-lg border border-input bg-card px-2 text-[11px] font-bold" value={a.status} onChange={(e) => update.mutate({ id: a.id, data: { status: e.target.value as 'accepted' | 'in_progress' | 'completed' | 'missed' | 'unable_to_collect' | 'skipped', notes: null, failureReason: null } }, { onSuccess: () => q.refetch() })} data-testid={`select-assignment-status-${a.id}`}><option value="accepted">Accepted</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="missed">Missed</option><option value="unable_to_collect">Unable to collect</option><option value="skipped">Skipped</option></select></div>)}</div> : <EmptyState icon={Truck} title="No assignments" text="Assigned collection tasks will appear here when your route is published." />}</Shell>;
}

function CollectorIncidents() { return <Shell role="collector"><PageHeader eyebrow="Field operations" title="Incidents" description="Exceptions that need a decision, a note, or another crew." actions={<Button variant="outline" onClick={() => window.alert('Incident logging is connected to your next field report.')} data-testid="button-new-incident"><Plus size={15} /> Log incident</Button>} /><EmptyState icon={AlertCircle} title="No active incidents" text="That is a good route. Keep this clear by recording exceptions as soon as they happen." /></Shell>; }

function AdminOverview() {
  const q = useGetAdminDashboard({ query: { queryKey: getGetAdminDashboardQueryKey() } }); const d = q.data;
  return <Shell role="admin"><PageHeader eyebrow="Operations control" title="Network overview" description="The service picture across residents, routes, and response queues." actions={<Link href="/admin/analytics" className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-3.5 py-2.5 text-xs font-bold hover:bg-muted" data-testid="link-open-analytics"><Activity size={15} /> Performance</Link>} />{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : d ? <><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatCard label="Today’s collections" value={d.todayCollections} detail={`${d.completedCollections} completed`} icon={CalendarDays} /><StatCard label="Completion rate" value={`${d.completionRate}%`} detail="Across today’s routes" icon={Gauge} tone="accent" /><StatCard label="Open complaints" value={d.openComplaints} detail={`${d.criticalComplaints} critical`} icon={FileText} tone={d.criticalComplaints ? 'danger' : 'primary'} /><StatCard label="Overflow reports" value={d.overflowReports} detail="Needs review" icon={AlertCircle} tone="accent" /></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><section className="surface rounded-2xl p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Service pulse</p><h2 className="mt-2 text-lg font-extrabold">At a glance</h2></div><span className="status status-green">Network live</span></div><div className="mt-6 grid gap-4 sm:grid-cols-3"><div className="rounded-xl bg-secondary p-4"><p className="eyebrow">Residents</p><p className="mt-3 text-3xl font-extrabold tracking-[-.07em]">{d.citizens}</p></div><div className="rounded-xl bg-muted p-4"><p className="eyebrow">Collectors</p><p className="mt-3 text-3xl font-extrabold tracking-[-.07em]">{d.collectors}</p></div><div className="rounded-xl bg-accent/20 p-4"><p className="eyebrow">Collection points</p><p className="mt-3 text-3xl font-extrabold tracking-[-.07em]">{d.collectionPoints}</p></div></div><div className="mt-7"><div className="mb-2 flex justify-between text-xs font-bold"><span>Completion progress</span><span className="mono text-[10px] text-muted-foreground">{d.completionRate}%</span></div><div className="progress-track"><div className="progress-fill" style={{ width: `${Math.min(100, d.completionRate)}%` }} /></div></div></section><section className="surface rounded-2xl p-5"><p className="eyebrow">Recent activity</p><div className="mt-5 divide-y divide-border">{d.activity?.slice(0, 5).map((a, i) => <div className="py-3 first:pt-0" key={`${a.title}-${i}`} data-testid={`admin-activity-${i}`}><div className="flex justify-between gap-2"><p className="text-xs font-bold">{a.title}</p><span className="mono text-[9px] text-muted-foreground">{a.timestamp}</span></div><p className="mt-1 text-[11px] leading-4 text-muted-foreground">{a.description}</p></div>)}</div></section></div></> : <EmptyState title="No network data" text="Operations metrics will appear once the service network reports in." />}</Shell>;
}

function AdminUsers({ collectors = false }: { collectors?: boolean }) {
  const q = useGetAdminUsers({}, { query: { queryKey: getGetAdminUsersQueryKey({}), enabled: true } }); const update = useUpdateAdminUserStatus(); const rows = (q.data ?? []).filter((u) => collectors ? u.role === 'collector' : true);
  return <Shell role="admin"><PageHeader eyebrow="Directory" title={collectors ? 'Collector roster' : 'Users'} description={collectors ? 'Keep field access current and accountable.' : 'Residents and operators with access to the service network.'} /><div className="mb-5 flex items-center gap-3"><div className="relative max-w-xs flex-1"><Search size={15} className="absolute left-3 top-3 text-muted-foreground" /><input className="field pl-9" placeholder="Search names or email" data-testid="input-user-search" /></div><span className="mono text-[10px] text-muted-foreground">{rows.length} records</span></div>{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : rows.length ? <div className="surface overflow-hidden rounded-2xl"><div className="hidden grid-cols-[1.2fr_1.2fr_.7fr_.7fr_auto] gap-4 border-b border-border bg-muted/45 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground sm:grid"><span>Person</span><span>Email</span><span>Role</span><span>Status</span><span>Access</span></div>{rows.map((u) => <div className="grid gap-3 border-b border-border px-5 py-4 last:border-0 sm:grid-cols-[1.2fr_1.2fr_.7fr_.7fr_auto] sm:items-center" key={u.id} data-testid={`row-user-${u.id}`}><div className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-full bg-secondary text-[10px] font-extrabold text-primary">{u.initials ?? u.fullName.slice(0, 2).toUpperCase()}</span><span className="text-xs font-bold">{u.fullName}</span></div><span className="text-xs text-muted-foreground">{u.email}</span><span className="text-xs font-semibold capitalize">{u.role}</span><Status value={u.status} /><select className="h-9 rounded-lg border border-input bg-card px-2 text-[11px] font-bold" value={u.status} onChange={(e) => update.mutate({ id: u.id, data: { status: e.target.value as 'active' | 'inactive' | 'suspended' } }, { onSuccess: () => q.refetch() })} data-testid={`select-user-status-${u.id}`}><option value="active">Active</option><option value="inactive">Inactive</option><option value="suspended">Suspended</option></select></div>)}</div> : <EmptyState icon={Users} title="No users found" text="Try a different search or check back when accounts are provisioned." />}</Shell>;
}

function AdminZones() {
  const q = useGetAdminZones({ query: { queryKey: getGetAdminZonesQueryKey() } }); const create = useCreateAdminZone(); const [form, setForm] = useState({ name: '', code: '' }); const [adding, setAdding] = useState(false); const rows = q.data ?? [];
  return <Shell role="admin"><PageHeader eyebrow="Network geography" title="Zones" description="The service map that keeps assignments and resident context grounded." actions={<Button onClick={() => setAdding((v) => !v)} variant="outline" data-testid="button-add-zone"><Plus size={15} /> Add zone</Button>} />{adding && <form className="surface mb-5 flex flex-col gap-2 rounded-2xl p-4 sm:flex-row sm:items-end" onSubmit={(e) => { e.preventDefault(); create.mutate({ data: { name: form.name, code: form.code, description: null } }, { onSuccess: () => { setAdding(false); setForm({ name: '', code: '' }); q.refetch(); } }); }}><label className="grid flex-1 gap-2 text-xs font-bold">Zone name<input required className="field" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} data-testid="input-zone-name" /></label><label className="grid w-full gap-2 text-xs font-bold sm:w-32">Code<input required className="field" value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} data-testid="input-zone-code" /></label><Button type="submit" disabled={create.isPending} data-testid="button-save-zone">{create.isPending ? 'Saving…' : 'Save zone'}</Button></form>}{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : rows.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{rows.map((z) => <div className="surface rounded-2xl p-5" key={z.id} data-testid={`card-zone-${z.id}`}><div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><MapPin size={17} /></span><Status value={z.active ? 'active' : 'inactive'} /></div><h2 className="mt-6 text-base font-extrabold">{z.name}</h2><p className="mono mt-1 text-[10px] text-muted-foreground">{z.code}</p><div className="mt-5 grid grid-cols-2 gap-3 border-t border-border pt-4"><div><p className="eyebrow">Points</p><p className="mt-1 text-lg font-extrabold">{z.points}</p></div><div><p className="eyebrow">Residents</p><p className="mt-1 text-lg font-extrabold">{z.residents}</p></div></div></div>)}</div> : <EmptyState icon={MapPin} title="No zones configured" text="Create the first service zone to begin mapping the network." />}</Shell>;
}

function AdminComplaints() {
  const q = useGetAdminComplaints({}, { query: { queryKey: getGetAdminComplaintsQueryKey({}), enabled: true } }); const update = useUpdateAdminComplaint(); const rows = q.data ?? [];
  return <Shell role="admin"><PageHeader eyebrow="Response queue" title="Complaint triage" description="Prioritize resident signals, assign ownership, and close the loop." /><div className="mb-5 flex flex-wrap gap-2"><span className="status status-red">Critical first</span><span className="status status-amber">Needs assignment</span><span className="status status-green">Resolved</span></div>{q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : rows.length ? <div className="surface overflow-hidden rounded-2xl">{rows.map((c) => <div className="grid gap-4 border-b border-border p-5 last:border-0 lg:grid-cols-[1.3fr_.7fr_.7fr_auto] lg:items-center" key={c.id} data-testid={`row-admin-complaint-${c.id}`}><div><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-bold">{c.title}</p><Status value={c.severity} /></div><p className="mt-1 text-xs text-muted-foreground">{c.location} · {c.citizenName}</p><p className="mono mt-2 text-[10px] text-muted-foreground">{new Date(c.createdAt).toLocaleString()}</p></div><div><p className="eyebrow">Status</p><div className="mt-2"><Status value={c.status} /></div></div><div><p className="eyebrow">Owner</p><p className="mt-2 text-xs font-bold">{c.assignedCollector ?? 'Unassigned'}</p></div><select className="h-9 rounded-lg border border-input bg-card px-2 text-[11px] font-bold" value={c.status} onChange={(e) => update.mutate({ id: c.id, data: { status: e.target.value as 'submitted' | 'acknowledged' | 'assigned' | 'in_progress' | 'resolved' | 'rejected', resolutionNote: null, assignedCollector: c.assignedCollector ?? null } }, { onSuccess: () => q.refetch() })} data-testid={`select-complaint-status-${c.id}`}><option value="submitted">Submitted</option><option value="acknowledged">Acknowledged</option><option value="assigned">Assigned</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="rejected">Rejected</option></select></div>)}</div> : <EmptyState icon={FileText} title="Queue is clear" text="No complaints are waiting for triage right now." />}</Shell>;
}

function AdminDataPage({ kind }: { kind: 'overflow' | 'analytics' | 'audit' | 'bins' | 'schedules' | 'assignments' | 'notifications' | 'ai' | 'settings' }) {
  const overflow = useGetAdminOverflowReports({ query: { queryKey: getGetAdminOverflowReportsQueryKey(), enabled: kind === 'overflow' } });
  const analytics = useGetAdminAnalytics({ query: { queryKey: getGetAdminAnalyticsQueryKey(), enabled: kind === 'analytics' } });
  const audit = useGetAdminAuditLogs({ query: { queryKey: getGetAdminAuditLogsQueryKey(), enabled: kind === 'audit' } });
  const ai = useGetAiHistory({ query: { queryKey: getGetAiHistoryQueryKey(), enabled: kind === 'ai' } });
  const config = { overflow: ['Overflow monitoring', 'Reports from residents and field teams that need a physical response.', AlertCircle], analytics: ['Performance analytics', 'A grounded read on collections, complaints, materials, and zones.', Activity], audit: ['Administrative audit trail', 'A durable record of changes made across the operating system.', ShieldCheck], bins: ['Bin monitoring', 'Collection point health and overflow risk across the network.', PackageCheck], schedules: ['Collection schedules', 'The published cadence for every zone and waste stream.', CalendarDays], assignments: ['Assignments', 'Who owns today’s work and where it is headed.', ClipboardCheck], notifications: ['Announcements', 'Share service changes with the people who rely on them.', Bell], ai: ['AI advisory history', 'Review guidance provided by the waste assistant.', Sparkles], settings: ['System settings', 'Operational defaults and account controls.', Settings] }[kind] as [string, string, IconType]; const q = kind === 'overflow' ? overflow : kind === 'analytics' ? analytics : kind === 'audit' ? audit : ai; const rows = (Array.isArray(q.data) ? q.data : []) as any[];
  return <Shell role="admin"><PageHeader eyebrow="Administration" title={config[0]} description={config[1]} actions={kind === 'notifications' ? <Button onClick={() => window.alert('Announcement composer opened for the operations team.')} data-testid="button-new-announcement"><Plus size={15} /> New announcement</Button> : undefined} />{kind === 'analytics' && analytics.data ? <AnalyticsView data={analytics.data} /> : kind === 'settings' ? <SettingsView /> : q.isLoading ? <LoadingState /> : q.isError ? <ErrorState retry={() => q.refetch()} /> : rows.length ? <DataRows kind={kind} rows={rows} /> : <EmptyState icon={config[2]} title={kind === 'overflow' ? 'No overflow reports' : 'No records yet'} text="When this area has activity, it will become the working queue for the team." />}</Shell>;
}

function DataRows({ kind, rows }: { kind: string; rows: any[] }) {
  return <div className="surface overflow-hidden rounded-2xl">{rows.map((row, i) => <div className="border-b border-border p-5 last:border-0" key={row.id ?? i} data-testid={`row-${kind}-${row.id ?? i}`}><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-sm font-bold">{row.location ?? row.action ?? row.question ?? row.title ?? 'Operational record'}</p><p className="mt-1 text-xs text-muted-foreground">{row.description ?? row.entity ?? row.answer ?? row.message ?? 'Recorded activity'}</p></div><div className="flex items-center gap-3">{row.severity && <Status value={row.severity} />}{row.status && <Status value={row.status} />}<span className="mono text-[10px] text-muted-foreground">{row.createdAt ?? row.timestamp ?? ''}</span></div></div></div>)}</div>;
}

function AnalyticsView({ data }: { data: any }) {
  const groups = [['Collections', data.collections], ['Complaints', data.complaints], ['Waste categories', data.wasteCategories], ['Zones', data.zones]] as [string, { label: string; value: number }[]][];
  return <div className="grid gap-5 md:grid-cols-2">{groups.map(([title, points]) => { const max = Math.max(...(points?.map((p) => p.value) ?? [1]), 1); return <section className="surface rounded-2xl p-5" key={title}><p className="eyebrow">{title}</p><div className="mt-6 grid gap-4">{points?.map((p) => <div key={p.label} data-testid={`metric-${title}-${p.label}`}><div className="mb-1 flex justify-between text-xs"><span className="font-semibold">{p.label}</span><span className="mono text-[10px] text-muted-foreground">{p.value}</span></div><div className="progress-track"><div className="progress-fill" style={{ width: `${(p.value / max) * 100}%` }} /></div></div>)}</div></section>; })}</div>;
}

function SettingsView() {
  const [saved, setSaved] = useState(false); return <div className="grid max-w-3xl gap-5"><section className="surface rounded-2xl p-6"><p className="eyebrow">Service defaults</p><h2 className="mt-2 text-lg font-extrabold">Operational preferences</h2><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="grid gap-2 text-xs font-bold">Default escalation window<select className="field" defaultValue="4"><option value="2">2 hours</option><option value="4">4 hours</option><option value="8">8 hours</option></select></label><label className="grid gap-2 text-xs font-bold">Daily digest time<input className="field" type="time" defaultValue="07:30" /></label></div></section><section className="surface flex flex-col justify-between gap-4 rounded-2xl p-6 sm:flex-row sm:items-center"><div><p className="text-sm font-bold">Save system settings</p><p className="mt-1 text-xs text-muted-foreground">Changes apply to the operations workspace.</p></div><Button onClick={() => setSaved(true)} data-testid="button-save-settings">{saved ? <><Check size={15} /> Saved</> : 'Save settings'}</Button></section></div>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch>
    <Route path="/" component={Landing} /><Route path="/login" component={Login} /><Route path="/register" component={Register} />
    <Route path="/citizen" component={CitizenOverview} /><Route path="/citizen/schedule" component={Schedules} /><Route path="/citizen/complaints/new" component={NewComplaint} /><Route path="/citizen/complaints/:id" component={ComplaintDetail} /><Route path="/citizen/complaints" component={CitizenComplaints} /><Route path="/citizen/assistant" component={Assistant} /><Route path="/citizen/notifications" component={() => <Notifications role="citizen" />} /><Route path="/citizen/profile" component={() => <Profile role="citizen" />} />
    <Route path="/collector" component={CollectorOverview} /><Route path="/collector/routes" component={() => <CollectorAssignments />} /><Route path="/collector/collections" component={() => <CollectorAssignments focus="collections" />} /><Route path="/collector/incidents" component={CollectorIncidents} /><Route path="/collector/notifications" component={() => <Notifications role="collector" />} /><Route path="/collector/profile" component={() => <Profile role="collector" />} />
    <Route path="/admin" component={AdminOverview} /><Route path="/admin/users" component={() => <AdminUsers />} /><Route path="/admin/collectors" component={() => <AdminUsers collectors />} /><Route path="/admin/zones" component={AdminZones} /><Route path="/admin/bins" component={() => <AdminDataPage kind="bins" />} /><Route path="/admin/schedules" component={() => <AdminDataPage kind="schedules" />} /><Route path="/admin/assignments" component={() => <AdminDataPage kind="assignments" />} /><Route path="/admin/complaints" component={AdminComplaints} /><Route path="/admin/overflow" component={() => <AdminDataPage kind="overflow" />} /><Route path="/admin/notifications" component={() => <AdminDataPage kind="notifications" />} /><Route path="/admin/ai-insights" component={() => <AdminDataPage kind="ai" />} /><Route path="/admin/analytics" component={() => <AdminDataPage kind="analytics" />} /><Route path="/admin/audit-logs" component={() => <AdminDataPage kind="audit" />} /><Route path="/admin/settings" component={() => <AdminDataPage kind="settings" />} />
    <Route component={NotFound} />
  </Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;